item.aggregated_output:
  border-top: 1px solid var(--line);
  padding-top: 26px;
  margin-top: 32px;
}
.currency-section > h2 {
  color: var(--accent);
}
.summary-columns {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 48px;
}
.summary-columns h3 {
  font-size: 16px;
  font-weight: 600;
  margin: 14px 0 12px;
}
.summary-columns table {
  width: 100%;
  table-layout: fixed;
  border-collapse: collapse;
  font-size: 14px;
  line-height: 1.6;
}
.summary-columns th,
.summary-columns td {
  text-align: left;
  vertical-align: top;
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
  overflow-wrap: anywhere;
}
.summary-columns thead th {
  font-size: 12px;
  font-weight: 400;
  color: var(--muted);
  padding-top: 0;
}
.summary-columns th {
  font-weight: 500;
  padding-right: 16px;
  width: 54%;
}
.summary-columns td,
.summary-columns th:last-child {
  text-align: right;
}
.entry-count,
.partial-note {
  display: block;
  font-size: 11px;
  font-weight: 400;
  line-height: 1.7;
  color: var(--muted);
  margin-top: 4px;
}
.ranking-note {
  margin: 0 0 12px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
}
.detail-footnote {
  margin-top: 32px;
  font-size: 12px;
}
.detail-message {
  padding: 32px 0 80px;
}
.detail-message p {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.8;
}
.detail-message .loading-indicator {
  display: block;
  margin-bottom: 24px;
}
.empty-details {
  padding: 24px 0;
}
@media (max-width: 700px) {
  .summary-columns {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }
  .declaration-heading {
    flex-direction: column;
    gap: 8px;
  }
  .back-link {
  margin-top: 24px;
}
.member-page .back-link {
  margin-bottom: 24px;
}
.member-identity .profile-type {
  margin-bottom: 0;
}
.member-summary-top {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  gap: 48px;
  padding-bottom: 32px;
  margin-bottom: 32px;
  border-bottom: 1px solid var(--line);
}

.member-earnings {
  min-width: 0;
  border-left: 1px solid var(--line);
  padding-left: 32px;
}
.member-breakdown .category-label {
  font-size: 13px;
  line-height: 1.65;
}
.member-breakdown .category-label .amount {
  flex-shrink: 0;
  max-width: 45%;
}
.member-page .declaration {
  padding: 18px 0;
}
.member-page .funding-list {
  margin-top: 12px;
}
@media (max-width: 800px) {
  .member-summary-top {
    grid-template-columns: minmax(0, 1fr);
    gap: 24px;
  }
  .member-earnings {
    border-left: 0;
    padding-left: 0;
  }
}

.member-identity {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, auto);
  gap: 16px 32px;
}
.member-tabs {
}
.party-tooltip strong {
  margin-top: 4px;
  font-variant-numeric: tabular-nums;
}
.funder-recipients {
  display: block;
  margin-bottom: 40px;
}
.funder-recipients table {
  width: 100%;
}
.funder-recorded-names {
  margin-top: 36px;
}
.funder-recorded-names summary {
  cursor: pointer;
  font-weight: 600;
}
.funder-page .declaration-heading a {
  color: inherit;
}
import type { FunderDetails } from "./entity-details";

const colors = [
  "#df8550",
  "#6587ad",
  "#b39e53",
  "#809c79",
  "#9a83b5",
  "#bf747c",
];

export function partyChart(
  parties: FunderDetails["currencies"][number]["parties"],
) {
  const scale = Math.max(
    0,
    ...parties.map((party) => party.amount?.split(".")[1]?.length ?? 0),
  );
  const values = parties.map(({ amount }) => {
    if (amount === null || amount.startsWith("-")) return 0n;
    const [whole, fraction = ""] = amount.split(".");
    return BigInt(whole + fraction.padEnd(scale, "0"));
  });
  const total = values.reduce((sum, value) => sum + value, 0n);
  let start = 0;
  return parties.map((party, index) => {
    const share =
      total === 0n ? 0 : Number((values[index] * 1000000n) / total) / 1000000;
    const angle = share * Math.PI * 2;
    const end = start + angle;
    const path =
      share === 0 || share === 1
        ? ""
        : `M 100 100 L ${100 + 90 * Math.sin(start)} ${100 - 90 * Math.cos(start)} A 90 90 0 ${share > 0.5 ? 1 : 0} 1 ${100 + 90 * Math.sin(end)} ${100 - 90 * Math.cos(end)} Z`;
    start = end;
    return { party, share, path, color: colors[index % colors.length] };
  });
}

